import AppKit
import AVFoundation
import CoreAudio

final class LiveRecorder {
    private var engine:AVAudioEngine?,player:AVAudioPlayer?
    private(set) var recording=false,requesting=false,rate:Double=48000
    var status="Ready • press F1 to record"
    var count:Int{Int(tm_capture_count())}
    var seconds:Double{Double(count)/rate}
    var inputName="Default input"
    func refreshInputName(){inputName=queryInputName()}
    private func queryInputName()->String{var address=AudioObjectPropertyAddress(mSelector:kAudioHardwarePropertyDefaultInputDevice,mScope:kAudioObjectPropertyScopeGlobal,mElement:kAudioObjectPropertyElementMain),id=AudioDeviceID(0),size=UInt32(MemoryLayout<AudioDeviceID>.size);guard AudioObjectGetPropertyData(AudioObjectID(kAudioObjectSystemObject),&address,0,nil,&size,&id)==noErr,id != 0 else{return "No input device"};address.mSelector=kAudioObjectPropertyName;var name:Unmanaged<CFString>?;size=UInt32(MemoryLayout<Unmanaged<CFString>?>.size);if AudioObjectGetPropertyData(id,&address,0,nil,&size,&name)==noErr,let n=name?.takeRetainedValue(){return n as String};return "Default input"}
    func toggle(){if recording{stop();return};guard !requesting else{return};switch AVCaptureDevice.authorizationStatus(for:.audio){case .authorized:start();case .notDetermined:status="Enable input first: H > Audio Setup > Start Audio + Enable Live Record";default:status="Input permission denied — System Settings > Privacy > Microphone, then Audio Setup"}}
    func start(){stopPreview();refreshInputName();let e=AVAudioEngine(),input=e.inputNode,format=input.outputFormat(forBus:0);guard format.sampleRate>=8000,format.sampleRate<=192000,format.channelCount>0,format.commonFormat == .pcmFormatFloat32,!format.isInterleaved else{status="No compatible default audio input";return};rate=format.sampleRate;tm_capture_begin();input.installTap(onBus:0,bufferSize:1024,format:format){buffer,_ in guard let c=buffer.floatChannelData else{return};_ = tm_capture_push(c[0],buffer.format.channelCount>1 ? c[1]:nil,Int32(buffer.frameLength))};do{e.prepare();try e.start();engine=e;recording=true;status="RECORDING • F1 Stop"}catch{input.removeTap(onBus:0);e.stop();status="Unable to start input: \(error.localizedDescription)"}}
    func stop(){requesting=false;if let e=engine{e.stop();e.inputNode.removeTap(onBus:0);engine=nil};recording=false;status=count>0 ? "Take ready • F2 Preview / F3 Add":"Ready • press F1 to record"}
    func tick(){if recording&&count>=1_000_000{stop();status="Take reached the 1M-frame sample limit"}}
    func discard(){stop();stopPreview();tm_capture_begin();status="Ready • press F1 to record"}
    func pcm()->Data{var samples=[Float](repeating:0,count:count);let n=samples.withUnsafeMutableBufferPointer{Int(tm_capture_copy($0.baseAddress,Int32($0.count)))};return samples.prefix(n).withUnsafeBytes{Data($0)}}
    func stopPreview(){player?.stop();player=nil}
    func preview(){guard !recording,count>0 else{return};if player?.isPlaying==true{stopPreview();return};let samples=SampleEditing.floats(pcm());var wav=Data();func u16(_ n:UInt16){var v=n.littleEndian;withUnsafeBytes(of:&v){wav.append(contentsOf:$0)}};func u32(_ n:UInt32){var v=n.littleEndian;withUnsafeBytes(of:&v){wav.append(contentsOf:$0)}};wav.append(Data("RIFF".utf8));u32(UInt32(36+samples.count*2));wav.append(Data("WAVEfmt ".utf8));u32(16);u16(1);u16(1);u32(UInt32(rate));u32(UInt32(rate)*2);u16(2);u16(16);wav.append(Data("data".utf8));u32(UInt32(samples.count*2));for f in samples{u16(UInt16(bitPattern:Int16(max(-32767,min(32767,f*32767)))))};do{player=try AVAudioPlayer(data:wav);player?.play()}catch{status="Preview failed: \(error.localizedDescription)"}}
}

extension Tracker {
    func openRecorder(){selectPage(10)}
    func storeRecording(_ granular:Bool,confirm:Bool=true){let r=liveRecorder;guard !r.recording,!r.requesting,r.count>0 else{r.status="Stop recording before adding a take";return};guard slots[instrumentRow].name=="EMPTY" || !confirm || proveOverwriteRecording() else{return};let data=r.pcm(),total=slots.enumerated().filter{$0.offset != instrumentRow}.reduce(data.count){$0+($1.element.pcm?.count ?? 0)};guard total<=64000000 else{r.status="Project sample memory limit: 64 MB";return};checkpoint();let formatter=DateFormatter();formatter.dateFormat="HHmmss";var p=SamplePlaybackSettings();p.mode=granular ? 5:0;p=p.normalized(data.count/4);var sl=slots;sl[instrumentRow]=InstrumentSlot(name:"REC-\(formatter.string(from:Date()))",wave:2,pcm:data,sampleRate:r.rate,root:60,playback:p);project.slots=sl;syncInstruments();r.stopPreview();r.status="Added to instrument \(instrumentRow+1)";if granular{let i=instrumentRow;selectPage(8);instrumentRow=i;waveCache=nil};needsDisplay=true}
    func proveOverwriteRecording()->Bool{let alert=NSAlert();alert.messageText="Replace instrument \(instrumentRow+1)?";alert.informativeText=slots[instrumentRow].name;alert.addButton(withTitle:"Replace");alert.addButton(withTitle:"Cancel");return alert.runModal() == .alertFirstButtonReturn}
    func recorderSoft(_ i:Int){switch i{case 0:liveRecorder.toggle();case 1:liveRecorder.preview();case 2:storeRecording(false);case 3:storeRecording(true);case 4:liveRecorder.discard();case 5:instrumentRow=max(0,instrumentRow-1);case 6:instrumentRow=min(47,instrumentRow+1);case 7:selectPage(7);default:break};needsDisplay=true}
    func recorderKey(_ e:NSEvent)->Bool{let ch=e.charactersIgnoringModifiers?.lowercased() ?? "",code=e.keyCode;if ch=="r"||code==49{if !e.isARepeat{liveRecorder.toggle()};return true};if code==36||code==76{storeRecording(false);return true};if code==53{selectPage(7);return true};if [123,126].contains(code)||ch=="q"{instrumentRow=max(0,instrumentRow-1);return true};if [124,125].contains(code)||ch=="e"{instrumentRow=min(47,instrumentRow+1);return true};return false}
    func drawRecorder(){let r=liveRecorder,w=bounds.width,x:CGFloat=36,y:CGFloat=150,ww=w-72,h=max(100,footerY-y-96);txt("LIVE SAMPLE RECORDER",40,64,14,teal,true);txt("Input: \(r.inputName)  /  macOS default input",40,94,12,gray(0.85));txt(String(format:"%.3f s  /  %.0f Hz  /  %d frames",r.seconds,r.rate,r.count),w*0.57,94,12,r.recording ? recColor:teal,true);rect(x,y,ww,h,gray(0.09));let columns=max(1,min(900,Int(ww))),mid=y+h/2;var low=[Float](repeating:0,count:columns),high=low;low.withUnsafeMutableBufferPointer{l in high.withUnsafeMutableBufferPointer{u in tm_capture_peaks(l.baseAddress,u.baseAddress,Int32(columns))}};let path=NSBezierPath();for i in 0..<columns{let xx=x+CGFloat(i)*ww/CGFloat(columns);path.move(to:NSPoint(x:xx,y:mid-CGFloat(high[i])*h*0.46));path.line(to:NSPoint(x:xx,y:mid-CGFloat(low[i])*h*0.46))};(r.recording ? recColor:teal).setStroke();path.lineWidth=1;path.stroke();rect(x,mid,ww,1,gray(0.43));txt(r.status,x,y+h+14,12,r.recording ? recColor:teal,true);txt("Destination: \(String(format:"%02d",instrumentRow+1))  \(slots[instrumentRow].name)  •  Q/E or arrows select slot",x,y+h+38,12,yellow);txt("No input monitoring. Select your mic/audio interface in macOS Sound > Input.",x,y+h+62,11,gray(0.7))}
}
